const data = items[0].json;

const rows = [];

// Saved from cache - first row before Total cost
rows.push({
  section: 'cacheReport',
  project: data.project.title,
  apiKey: data.apiKey.name,
  name: data.overview.cacheReport.savedFromCache.label,
  key: 'saved_from_cache',
  value: data.overview.cacheReport.savedFromCache.value,
  description: 'Estimated LLM cost saved from repeated prompts served by FlowGuard cache',
  workflow: '',
  node: '',
  model: '',
  tokens: '',
  cost: data.overview.cacheReport.savedFromCache.value,
  latency: '',
  status: ''
});

// Metrics
for (const metric of data.overview.metrics || []) {
  rows.push({
    section: 'metrics',
    project: data.project.title,
    apiKey: data.apiKey.name,
    name: metric.label,
    key: metric.key,
    value: metric.value,
    description: metric.description || '',
    workflow: '',
    node: '',
    model: '',
    tokens: '',
    cost: '',
    latency: '',
    status: ''
  });
}

// Cache report details
rows.push({
  section: 'cacheReport',
  project: data.project.title,
  apiKey: data.apiKey.name,
  name: data.overview.cacheReport.cachedCalls.label,
  key: 'cached_calls',
  value: data.overview.cacheReport.cachedCalls.value,
  description: 'Provider calls avoided by cache',
  workflow: '',
  node: '',
  model: '',
  tokens: '',
  cost: '',
  latency: '',
  status: ''
});

rows.push({
  section: 'cacheReport',
  project: data.project.title,
  apiKey: data.apiKey.name,
  name: data.overview.cacheReport.hitRate.label,
  key: 'hit_rate',
  value: data.overview.cacheReport.hitRate.value,
  description: 'Cache hit rate',
  workflow: '',
  node: '',
  model: '',
  tokens: '',
  cost: '',
  latency: '',
  status: ''
});

// Top workflows by cost
for (const workflow of data.overview.topWorkflowsByCost || []) {
  rows.push({
    section: 'topWorkflowsByCost',
    project: data.project.title,
    apiKey: data.apiKey.name,
    name: workflow.name,
    key: '',
    value: '',
    description: '',
    workflow: workflow.name,
    node: '',
    model: '',
    tokens: workflow.tokens,
    cost: workflow.cost,
    latency: '',
    status: workflow.status
  });
}

// Top nodes by cost
for (const node of data.overview.topNodesByCost || []) {
  rows.push({
    section: 'topNodesByCost',
    project: data.project.title,
    apiKey: data.apiKey.name,
    name: node.name,
    key: '',
    value: '',
    description: '',
    workflow: node.workflow,
    node: node.name,
    model: '',
    tokens: '',
    cost: node.cost,
    latency: node.latency,
    status: node.status
  });
}

// Recent requests
for (const request of data.overview.recentRequests || []) {
  rows.push({
    section: 'recentRequests',
    project: data.project.title,
    apiKey: data.apiKey.name,
    name: '',
    key: '',
    value: '',
    description: '',
    workflow: request.workflow,
    node: request.node,
    model: request.model,
    tokens: request.tokens,
    cost: request.cost,
    latency: '',
    status: request.status
  });
}

const headers = Object.keys(rows[0]);

function escapeCsv(value) {
  if (value === null || value === undefined) return '';
  const str = String(value);
  return `"${str.replace(/"/g, '""')}"`;
}

const csv = [
  headers.join(','),
  ...rows.map(row => headers.map(header => escapeCsv(row[header])).join(','))
].join('\n');

return [
  {
    json: {
      fileName: 'flowguard-report.csv',
      savedFromCache: data.overview.cacheReport.savedFromCache.value
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(csv, 'utf8'),
        'flowguard-report.csv',
        'text/csv'
      )
    }
  }
];
